inline const APL *GetAPL(const void *buf) {
  return ::flatbuffers::GetRoot<APL>(buf);
}

inline const APL *GetSizePrefixedAPL(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<APL>(buf);
}

inline const char *APLIdentifier() {
  return "$APL";
}

inline bool APLBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, APLIdentifier());
}

inline bool SizePrefixedAPLBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, APLIdentifier(), true);
}

template <bool B = false>
inline bool VerifyAPLBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<APL>(APLIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedAPLBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<APL>(APLIdentifier());
}

inline void FinishAPLBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<APL> root) {
  fbb.Finish(root, APLIdentifier());
}

inline void FinishSizePrefixedAPLBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<APL> root) {
  fbb.FinishSizePrefixed(root, APLIdentifier());
}

inline std::unique_ptr<APLT> UnPackAPL(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<APLT>(GetAPL(buf)->UnPack(res));
}

inline std::unique_ptr<APLT> UnPackSizePrefixedAPL(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<APLT>(GetSizePrefixedAPL(buf)->UnPack(res));
}

